<?php declare(strict_types=1);?><section class="page-intro"><div><span class="kicker">TRADERPROFIEL</span><h1><?=h($name)?></h1><p><?= $summary ? (int)$summary['messages'].' berichten · actief van '.h($summary['first_seen']).' tot '.h($summary['last_seen']) : 'Geen gegevens gevonden.'?></p></div></section><div class="grid"><section class="surface"><div class="section-heading"><h2>Gestructureerde aanbiedingen</h2><span class="muted"><?=count($offers)?></span></div><div class="tablewrap"><table><thead><tr><th>Type</th><th>Item</th><th>Prijs</th><th>Moment</th></tr></thead><tbody><?php foreach($offers as$o):?><tr><td><span class="badge <?=h($o['trade_type'])?>"><?=h(strtoupper((string)$o['trade_type']))?></span></td><td><?=h($o['item'])?></td><td><?= $o['unit_price_ecto']!==null ? number_format((float)$o['unit_price_ecto'],2,',','.').'e' : '—'?></td><td class="muted"><?=h($o['posted_at'])?></td></tr><?php endforeach;?></tbody></table></div></section><aside class="surface"><div class="section-heading"><h2>Recente berichten</h2></div><?php foreach(array_slice($messages,0,20) as$m):?><article class="callout"><p><?=h($m['message'])?></p><small class="muted"><?=h($m['posted_at'])?></small></article><?php endforeach;?></aside></div>